import Foundation

/// UI language only. Service IDs, voice IDs, stored keys and user text are unchanged.
public nonisolated enum SettingsDisplayLanguage: String, Codable, CaseIterable, Sendable {
    case japanese = "ja"
    case english = "en"
    public static var systemDefault: Self {
        preferred(for: Locale.preferredLanguages)
    }
    public static func preferred(for languages: [String]) -> Self {
        languages.first?.lowercased().hasPrefix("ja") == true ? .japanese : .english
    }
    public var nativeLabel: String { self == .japanese ? "日本語" : "English" }
}

/// Stable catalog shared by both settings hosts. Unknown keys retain their fallback.
public nonisolated enum CastorSettingsStrings {
    public static func text(_ key: String, language: SettingsDisplayLanguage, arguments: [String: String] = [:], fallback: String? = nil) -> String {
        guard let entry = entries[key] else { return fallback ?? key }
        let template = language == .japanese ? entry.japanese : entry.english
        // Replace in a single pass so values containing braces are never interpreted again.
        var result = ""
        var remainder = template[...]
        while let opening = remainder.firstIndex(of: "{"), let closing = remainder[opening...].firstIndex(of: "}") {
            result += remainder[..<opening]
            let name = String(remainder[remainder.index(after: opening)..<closing])
            result += arguments[name] ?? String(remainder[opening...closing])
            remainder = remainder[remainder.index(after: closing)...]
        }
        return result + remainder
    }
    public static func label(_ source: String, language: SettingsDisplayLanguage) -> String {
        for (prefix, key) in [("Unavailable: ", "settings.service.unavailable"), ("Stopped: ", "settings.agent.stopped_detail")] {
            if source.hasPrefix(prefix) { return text(key, language: language, arguments: ["detail": String(source.dropFirst(prefix.count))]) }
        }
        for (suffix, key) in [(" Install the Codex CLI and sign in, then turn this on again.", "settings.agent.install_codex"), (" Install Claude Code and sign in, then turn this on again.", "settings.agent.install_claude")] {
            if source.hasSuffix(suffix) { return String(source.dropLast(suffix.count)) + " " + text(key, language: language) }
        }
        guard let key = sourceKeys[source] else { return source }
        return text(key, language: language, fallback: source)
    }
    public static var keys: [String] { entries.keys.sorted() }
    private struct Entry: Sendable { let japanese: String; let english: String }
